    // base should preserve reference from other element
    // @ts-expect-error
    pathItem.base = prevCoords;
    // @ts-expect-error
    pathItem.coords = [cursor[0], cursor[1]];
    // @ts-expect-error
    prevCoords = pathItem.coords;
